const IDX = { de: 0, fr: 1, it: 2, en: 3 };
let cur = 'de';
export function setLang(l) { cur = IDX[l] !== undefined ? l : 'de'; }
export function locale(l = cur) { return { de: 'de-CH', fr: 'fr-CH', it: 'it-CH', en: 'en-GB' }[l] || 'de-CH'; }

export function t(key, vars = {}, lang) {
  const e = D[key];
  if (!e) return key;
  let s = e[IDX[lang || cur]] || e[0];
  for (const k in vars) s = s.split(`{${k}}`).join(vars[k]);
  return s;
}

